import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdir, mkdtemp, writeFile, open } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { IMAGE_LIMITS, CLIPBOARD_TOKEN_TYPE, inspectImageBytes, readImageFile, prepareImageAsset, ImageInputService } from '../app/image-input.mjs';

// Original 7x5 solid color, generated by the project's Chromium canvas fixture.
const png = Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAcAAAAFCAYAAACJmvbYAAAAJElEQVR4AbTJMQ0AAAwCwQYllVD/KuoIFMDGJz8dfo9uTKiEAgAA//9gSBKgAAAABklEQVQDAJPZDuSiKyB0AAAAAElFTkSuQmCC', 'base64');
const gif = Buffer.from('47494638396102000100800000ff00000000ff21f904000a0000002c0000000002000100000202040a0021f904000a0000002c00000000020001000002024c0a003b', 'hex');
const fakeDecode = async (_, info) => ({ naturalWidth: info.width || 2, naturalHeight: info.height || 2, src: `data:image/png;base64,${png.toString('base64')}` });
class ClipItem { constructor(data) { this.data = data; this.types = Object.keys(data); } async getType(type) { const value = this.data[type]; return value instanceof Blob ? value : new Blob([value]); } }
function fixture() { let items = []; const clipboard = { read: async () => items, write: async value => { items = value; } }; return { clipboard, service: new ImageInputService({ clipboard, ClipboardItem: ClipItem, decode: fakeDecode }) }; }

test('输入预检不靠文件扩展名，保留动画格式和原始字节', async () => {
  assert.equal(inspectImageBytes(png).format, 'png'); const info = inspectImageBytes(gif); assert.equal(info.frames, 2); assert.equal(info.animated, true);
  const asset = await prepareImageAsset({ bytes: gif, name: 'not-a-png.png' }, fakeDecode); assert.equal(asset.mime, 'image/gif'); assert.equal(asset.converted, false); assert.deepEqual(Buffer.from(asset.src.split(',')[1], 'base64'), gif);
});
test('损坏、截断和超像素图片在解码前拒绝', async () => {
  for (const bytes of [Buffer.from('hello'), png.subarray(0, png.length - 5), gif.subarray(0, gif.length - 1)]) assert.throws(() => inspectImageBytes(bytes));
  const large = Buffer.from(png); large.writeUInt32BE(9000, 16); let calls = 0;
  await assert.rejects(prepareImageAsset({ bytes: large }, async () => { calls++; })); assert.equal(calls, 0);
  assert.throws(() => inspectImageBytes(Buffer.alloc(IMAGE_LIMITS.bytes + 1)));
});
test('磁盘输入限定普通文件与4MiB，返回名称和字节不泄漏路径', async () => {
  const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../.local/image-input-tests'); await mkdir(root, { recursive: true }); const dir = await mkdtemp(path.join(root, 'run-'));
  const file = path.join(dir, 'own.png'); await writeFile(file, png); const result = await readImageFile(file); assert.equal(result.name, 'own.png'); assert.deepEqual(result.bytes, png); assert.equal(Object.hasOwn(result, 'path'), false);
  await assert.rejects(readImageFile(dir)); const big = path.join(dir, 'big.png'), handle = await open(big, 'w'); try { await handle.truncate(IMAGE_LIMITS.bytes + 1); } finally { await handle.close(); } await assert.rejects(readImageFile(big), /4 MiB/);
});
test('同一系统标记才粘贴内部元件，之后图片或文字不回退旧副本', async () => {
  const { service, clipboard } = fixture(), { token } = await service.markInternal('project');
  assert.deepEqual(await service.readPaste({ projectId: 'project', internalToken: token }), { kind: 'internal', token });
  assert.equal((await service.readPaste({ projectId: 'other', internalToken: token })).kind, 'empty');
  await clipboard.write([new ClipItem({ 'image/gif': new Blob([gif]), 'image/png': new Blob([png]), [CLIPBOARD_TOKEN_TYPE]: token })]);
  const pasted = await service.readPaste({ projectId: 'project', internalToken: token }); assert.equal(pasted.kind, 'images'); assert.equal(pasted.images[0].mime, 'image/gif');
  await clipboard.write([new ClipItem({ 'text/plain': '别处新复制的文字' })]); assert.equal((await service.readPaste({ projectId: 'project', internalToken: token })).kind, 'empty');
});
test('剪贴板超限与伪PNG被拒绝，不覆盖已有系统内容', async () => {
  const { service, clipboard } = fixture(), { token } = await service.markInternal('project');
  await assert.rejects(service.writeImage('data:image/png;base64,' + gif.toString('base64')), /不是 PNG/);
  assert.equal((await service.readPaste({ projectId: 'project', internalToken: token })).kind, 'internal');
  await clipboard.write([new ClipItem({ 'image/png': new Blob([Buffer.alloc(IMAGE_LIMITS.bytes + 1)]) })]); await assert.rejects(service.readPaste({ projectId: 'project', internalToken: token }), /4 MiB/);
});
test('PNG复制经过解码验证；转换后超限失败且输入对象保持不变', async () => {
  const { service, clipboard } = fixture(); await service.writeImage(`data:image/png;base64,${png.toString('base64')}`); assert.equal((await clipboard.read())[0].types[0], 'image/png');
  const bytes = Buffer.from('<svg xmlns="http://www.w3.org/2000/svg" width="2" height="2"/>'), before = Buffer.from(bytes);
  await assert.rejects(prepareImageAsset({ bytes }, async () => ({ naturalWidth: 2, naturalHeight: 2, src: `data:image/png;base64,${Buffer.alloc(IMAGE_LIMITS.bytes + 1).toString('base64')}` })), /超过 4 MiB/); assert.deepEqual(bytes, before);
});
